const founder=()=>section('about',`<div class="founder"><div class="portrait">${img('artem-portrait','Артём Болдырев, архитектор и основатель бюро')}</div><div>${label('Основатель бюро')}<h2>Артём<br>Болдырев</h2><p class="lead">Архитектор. Руководит командой, которая объединяет архитектуру, интерьеры и сопровождение реализации.</p><p>На первой встрече обсуждаем не только внешний вид дома: определяем требования к участку, планировке, конструкциям и бюджету строительства.</p><div class="founder-facts"><div><strong>10+ лет</strong><span>Практики бюро</span></div><div><strong>300+</strong><span>Клиентов бюро</span></div><div><strong>3 канала</strong><span>Проекты команды на ТВ</span></div></div><p class="small">Опыт бюро включает архитектуру и интерьеры. Телевизионные проекты — на ТНТ, ТВ-3 и «России 1».</p><ul class="plain-list"><li>Высшее архитектурное образование</li><li>Личное участие в обсуждении задачи и ключевых решений</li><li>Согласованная работа архитекторов и профильных специалистов</li></ul>${formButton('Обсудить задачу с архитектором','Хочу обсудить задачу с Артёмом Болдыревым.')}</div></div>`);

const checklist=()=>section('start-checklist',`${head('Подготовка к проектированию','Что подготовить<br>для старта?','Начните с того, что уже есть: участок, пожелания, референсы и ориентир бюджета. Техническое задание составим вместе на встрече — вам не нужно готовить его самостоятельно.')}<div class="checklist-grid">${window.START_CHECKLIST.map((g,i)=>`<article><span class="item-index">${String(i+1).padStart(2,'0')} / ${g.stage}</span><h3>${g.title}</h3><ul>${g.items.map((t,j)=>`<li><label><input type="checkbox" data-checklist="${i}-${j}"><span>${t}</span></label></li>`).join('')}</ul></article>`).join('')}</div><div class="download-bar"><div><strong>Чек-лист начала проектирования</strong><p>PDF · 3 страницы · можно сохранить и распечатать</p></div><a class="btn" href="downloads/Project-Doma-Start-Checklist.pdf" download>Скачать чек-лист PDF <span class="arrow">↓</span></a></div><p class="small checklist-progress" role="status">Отмечено: 0 из 18</p>`,'panel checklist-section');
