const pricingBlock=()=>section('pricing',`${head('Состав проекта','От концепции<br>до рабочих чертежей','Составим предложение под вашу задачу. Каждый следующий этап развивает утверждённые решения; точный перечень листов и разделов согласуем до договора.')}<div class="pricing-grid">${[['Архитектурная концепция','Чтобы выбрать образ дома',['Обсуждение сценариев жизни и требований','Варианты планировок и объёма','Цветовые и материальные решения фасадов','Визуализации архитектурной идеи','Предварительное размещение на участке']],['Эскиз и архитектурные решения','Чтобы детально проработать архитектуру',['Уточнение и согласование эскиза','Планы этажей с размерами','Фасады и разрезы','План кровли и ведомости проёмов','Рабочие архитектурные узлы по заданию']],['Полный комплект разделов','Чтобы подготовиться к строительству',['Архитектурные решения — АР','Конструктивные решения — КР','Отопление и вентиляция','Водоснабжение и канализация','Электроснабжение и согласование систем']]].map(([n,p,items],i)=>`<article><span class="item-index">0${i+1} / Состав работ</span><h3>${n}</h3><p class="package-purpose">${p}</p><ul class="plain-list">${items.map(t=>`<li>${t}</li>`).join('')}</ul>${formButton('Получить предложение','Интересует состав: '+n+'.')}</article>`).join('')}</div><p class="small tariff-note">Стоимость рассчитываем индивидуально. Авторский надзор и комплектацию обсуждаем отдельно: определяем задачи, период и формат участия бюро.</p><a class="text-link" href="#estimate">Указать параметры моего дома ↓</a>`,'panel');

const documentsBlock=()=>section('documents',`${head('Пример результата','Посмотрите, как<br>устроен проект','Ниже — отдельные листы для знакомства с подачей чертежей. На консультации покажем полный альбом и объясним, какие разделы нужны для вашего дома.')}<div class="document-grid">${['doc1','doc2','doc3'].map((n,i)=>`<button class="document-preview" data-gallery="${n}" aria-label="Открыть пример чертежа ${i+1}">${img(n,'Пример листа проекта '+(i+1))}<span>Рассмотреть лист ↗</span></button>`).join('')}</div><div class="document-downloads">${formButton('Запросить полный альбом','Хочу познакомиться с полным альбомом проекта и обсудить состав документации.')}</div><p class="small album-note">Подберём пример под вашу задачу и согласуем способ знакомства с материалами.</p>`);

const faqBlock=()=>section('faq',`${head('До начала работы','Вопросы о проектировании')}<div class="faq">${[['Сколько времени занимает проектирование?','Срок зависит от площади, сложности и состава разделов. После обсуждения исходных данных согласуем график разработки и промежуточных решений.'],['Какие документы входят в проект?','В зависимости от выбранного состава: эскизная концепция, архитектурные чертежи, конструктивные решения и инженерные системы. Подробный перечень фиксируем в задании.'],['Можно ли вносить изменения?','Да. Эскиз согласуется до детализации. Количество итераций и порядок изменений после утверждения этапа определяем в договоре.'],['Какие согласования нужны?','Это зависит от участка, ограничений и параметров объекта. Проверяем исходные данные и определяем необходимые действия для вашей ситуации.'],['Что подготовить к первой встрече?','Адрес или кадастровый номер участка, пожелания к площади и помещениям, референсы, ориентир бюджета и сроки. Техническое задание подготовим вместе с вами. Чек-лист исходных данных можно скачать на этой странице.'],['От чего зависит цена?','От площади, сложности архитектуры, конструкций и состава инженерных разделов. Оставьте параметры дома для расчёта: итоговую стоимость определяем после изучения задачи и согласования состава работ.'],['Можно адаптировать проект для другого участка?','Сначала проверяем рельеф, геологию, климат, ориентацию и ограничения. После этого определяем, какие решения можно сохранить, а какие нужно переработать.'],['Есть ли сопровождение строительства?','Можно согласовать авторский надзор и взаимодействие с подрядчиками. Формат и частота выездов зависят от объекта и объёма работ.']].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div><div class="section-action">${formButton('Задать свой вопрос','Хочу задать вопрос о проектировании.')}</div>`);
const hero=(servicePage=false)=>section('hero',`<div class="hero-photo">${img(servicePage?'potapovskie-4':'potapovskie-1','Загородный дом из портфолио бюро')}</div><div class="hero-shade"></div><div class="hero-content">${label(servicePage?'Индивидуальное проектирование':'Частные дома · Архитектура · Строительство')}<h1>${servicePage?'Дом для вашей семьи<br>Проект для<br>строительства':'Архитектура дома,<br>в котором<br>хочется жить'}</h1><p>${servicePage?'Создадим проект загородного дома: от планировок и фасадов до конструкций и инженерных систем.':'Проектируем частные дома под участок, привычки семьи и бюджет. Соединяем архитектуру, инженерные решения и сопровождение стройки.'}</p><div class="hero-actions"><a class="btn" href="#estimate">Получить расчёт${arrow}</a>${formButton(servicePage?'Обсудить мой дом':'Встретиться с архитектором','',true)}</div></div><div class="hero-bottom"><span>АРХИТЕКТУРНОЕ БЮРО АРТЁМА БОЛДЫРЕВА</span><a href="catalog.html">Смотреть проекты ↓</a></div>`,'architectural-hero');
const home=()=>`${header}<main>${hero()}${section('portfolio',`${head('Портфолио','Дома с разным характером')}<div class="project-grid">${projects.map(card).join('')}</div><div class="section-action">${link('Все проекты домов','catalog.html')}</div>`,'panel')}${section('architecture',`${head('Архитектурный характер','Увидеть свой дом<br>до начала строительства')}<div class="split-content"><div>${img('serebryany-1','Архитектура загородного дома')}</div><div><p class="lead">Сравните варианты объёма, планировки и фасадов. Выберите направление, которое соответствует вам и месту.</p><ul class="plain-list"><li>Варианты для обсуждения и согласования</li><li>3D-визуализации архитектурного образа</li><li>Материалы и пропорции в общей композиции</li><li>Согласованное решение для вашего участка</li></ul>${formButton('Обсудить архитектуру дома','Хочу обсудить архитектуру и референсы будущего дома.')}</div></div>`)}${section('services',`${head('Направления работы','От архитектурной идеи<br>до реализации дома')}<div class="service-grid">${[['Архитектурная концепция','Образ дома, планировки, цветовые решения фасадов и размещение на участке.','service.html#pricing','proekty1'],['Эскизный проект','Согласованный объём, планы, фасады и разрезы — основа дальнейшей разработки.','service.html#pricing','proekty2'],['Архитектурные решения','Рабочие планы, кровля, ведомости и узлы для реализации архитектуры.','service.html#documents','proekty3'],['Конструктивные решения','Расчёты и чертежи несущих элементов: от фундамента до кровли.','service.html#stages','drawing'],['Инженерные системы','Отопление, вентиляция, вода, канализация и электрика в согласованном проекте.','service.html#stages','doc3'],['Надзор и комплектация','Вопросы со стройки, проверка соответствия проекту, подбор материалов и поставщиков.','service.html#stages','house506']].map(([t,d,u,p],i)=>`<a href="${u}" class="service-tile">${img(p,t)}<div><span class="item-index">0${i+1}</span><h3>${t}</h3><p>${d}</p><span class="text-link">Подробнее ↗</span></div></a>`).join('')}</div>`)}${section('first-steps',`${head('С чего начинается сотрудничество','Сначала определим задачу<br>и бюджет строительства')} ${gridItems([['Первый разговор','Обсуждаем участок, ожидания, бюджет и желаемый результат.'],['Встреча и задание','Фиксируем состав помещений, стиль и требования к будущему дому.'],['Исходные данные','Проверяем документы и определяем, каких исследований не хватает.'],['Предложение и договор','Согласуем стоимость, состав работ, сроки и порядок утверждения решений.']],'four-grid')}<div class="section-action">${formButton('Начать с консультации')}</div>`)}${section('advantages',`${head('Подход бюро','Надёжность, удобство<br>и бюджет строительства')} ${gridItems([['Надёжность по расчётам','Конструкции разрабатываем с учётом геологии и нагрузок. Архитектура опирается на технически обоснованные решения.'],['Понятный бюджет','До детализации обсуждаем площадь, технологии и материалы. Сравниваем решения с финансовыми рамками строительства.'],['Чертежи для подрядчика','Согласуем архитектуру, конструкции и инженерные разделы, чтобы ключевые вопросы решались до выхода на площадку.'],['Удобство для семьи','Планируем приватные и общие помещения, хранение и маршруты с учётом привычек взрослых и детей.'],['Выразительная архитектура','Подбираем пропорции, материалы и остекление под ваш вкус, окружение и особенности участка.'],['Сопровождение реализации','В рамках авторского надзора отвечаем на вопросы подрядчика и проверяем соответствие работ проекту.']])}`,'panel')}${calc()}${stepsBlock('complete-project')}${section('budget',`${head('Управление бюджетом','Учитываем бюджет строительства<br>ещё в проекте')}<div class="split-content"><div class="technical-image">${img('drawing','Архитектурная документация')}</div>${gridItems([['Финансовые рамки','Разделяем бюджет на коробку, инженерию, отделку и участок. Определяем, что нужно построить в первую очередь.'],['Сравнение вариантов','Обсуждаем, как площадь, пролёты, остекление и материалы влияют на стоимость реализации.'],['Основа для сметы','Передаём согласованный комплект для расчёта работ и материалов. Подрядчики считают один и тот же объём.'],['Согласованные изменения','Если меняются пожелания, сначала обсуждаем последствия для проекта, бюджета и графика строительства.']],'two-grid')}</div><div class="section-action"><a class="btn" href="#estimate">Получить расчёт ↓</a></div>`,'panel')}${section('structure',`${head('Конструктивные решения','Надёжность начинается<br>с исходных данных')} ${gridItems([['Участок и геология','Смотрим на рельеф, грунты и условия участка до выбора фундамента.'],['Совместная работа с конструктором','Архитектура и несущая схема развиваются вместе, а не исправляются на стройке.'],['Расчёты и рабочие узлы','Материалы, перекрытия и соединения обосновываются проектными решениями.']])}`,'panel')}${section('supervision',`${head('Реализация','Помогаем сохранить замысел<br>на строительной площадке')} ${gridItems([['Подрядчики и поставщики','Помогаем организовать взаимодействие участников в рамках согласованного сопровождения.'],['Материалы по проекту','Проверяем соответствие выбранных материалов и решений документации.'],['Вопросы со стройки','Разбираем сложные узлы и изменения с ответственными специалистами.'],['Проверка результата','Фиксируем отклонения и обсуждаем способы их устранения.']],'four-grid')}<div class="section-action">${formButton('Обсудить сопровождение стройки','Интересует авторский надзор и сопровождение строительства.')}</div>`)}${founder()}${reviewsBlock()}${videosBlock()}${clientBlock()}${tvBlock()}${journalBlock()}${checklist()}${consultation()}</main>${footer}`;
const service=()=>`${header}<main>${hero(true)}${section('service-value',`${head('Индивидуальный проект','Дом под вашу жизнь,<br>а не жизнь под готовую планировку')}<div class="split-content"><div>${img('zoryanka-4','Частный загородный дом')}</div><div><p class="lead">Проектируем дом с учётом участка, состава семьи и ваших ежедневных привычек. От первых идей до согласованных чертежей.</p><ul class="plain-list"><li>Состав и связи помещений под ваш сценарий жизни</li><li>Посадка дома с учётом рельефа, света и окружения</li><li>Архитектурные и технические решения в одном проекте</li><li>Проверка исходных данных и требований к участку</li></ul></div></div>`)}${section('house-types',`${head('Что проектируем','У каждого дома —<br>своя задача')}<div class="types-grid">${[['Один этаж','Все повседневные маршруты на одном уровне. Проверим, как разместить нужные помещения на участке.'],['Два этажа','Разделим общие и личные пространства. Продуманные лестница и связи помещений экономят лишние переходы.'],['Компактный дом до 200 м²','Определим необходимый набор комнат и хранения без избыточной площади.'],['Дом от 200 до 350 м²','Совместим личные комнаты, общие зоны, рабочее место и гостевые сценарии.'],['Дом более 350 м²','Согласуем расширенную программу: дополнительные помещения, оборудование и связи между зонами.'],['Архитектура в вашем стиле','Современный дом, классика, шале или скандинавский характер — отберём референсы и сформируем цельный образ.']].map(([t,d],i)=>`<article><button class="image-button" data-gallery="${['serebryany-1','potapovskie-4','zoryanka-1','rostoshi-white-2','forest-roof-1','rostoshi-brick-1'][i]}" aria-label="Рассмотреть: ${t}">${img(['serebryany-1','potapovskie-4','zoryanka-1','rostoshi-white-2','forest-roof-1','rostoshi-brick-1'][i],t)}<span class="image-zoom">+</span></button><h3>${t}</h3><p>${d}</p>${formButton('Обсудить такой дом','Интересует '+t.toLowerCase()+'.',true)}</article>`).join('')}</div>`,'panel')}${section('individual-benefits',`${head('Возможности индивидуального проекта','Что вы получаете<br>от индивидуального проекта')} ${gridItems([['Уверенность в надёжности','Конструктивные решения основаны на исходных данных, исследованиях и расчётах.'],['Контроль расходов','Площадь, материалы и технологии выбираем с учётом бюджета реализации.'],['Место для каждого','Работа, отдых, гости и личное пространство получают своё место в планировке.'],['Комфортный климат','Учитываем отопление, вентиляцию и размещение оборудования на этапе проекта.'],['Приватность','Окна, террасы и входы располагаем с учётом соседей, улицы и маршрутов по участку.'],['Понятная стройка','Смежные разделы согласованы, а подрядчик получает чертежи и спецификации.'],['Архитектура по вашему вкусу','Обсуждаем референсы и выбираем решения, которые подходят дому и окружению.'],['Меньше переделок','Проверяем взаимосвязанные решения до строительства и обсуждаем изменения заранее.']],'four-grid')}<div class="reference-cta"><h3>Есть картинка или планировка,<br>которая вам нравится?</h3><p>Разберём, какие идеи подходят вашему участку. На их основе сформируем задание на индивидуальный проект.</p>${formButton('Разобрать мой референс','У меня есть картинка или планировка. Хочу обсудить, как использовать её идеи для моего участка.')}</div>`)}${section('examples',`${head('Примеры архитектуры','Найдите направление<br>для своего дома')}<div class="types-grid">${[['Современная архитектура','primer1','Современный'],['Классический коттедж','primer2','Классический'],['Скандинавский характер','primer3','Скандинавский'],['Дом с мансардой','primer4','Мансарда'],['Один этаж','primer5','1'],['Архитектура шале','primer6','Шале']].map(([t,p,q])=>`<article><button class="image-button" data-gallery="${p}" aria-label="Рассмотреть: ${t}">${img(p,t)}<span class="image-zoom">+</span></button><h3>${t}</h3><a class="text-link" href="catalog.html?${q==='1'?'floors':q==='Мансарда'?'floorTags':'style'}=${encodeURIComponent(q==='Мансарда'?'С мансардой':q)}">Подобрать проекты ↗</a></article>`).join('')}</div><div class="section-action">${link('Все проекты домов','catalog.html')}</div>`,'panel')}${pricingBlock()}${calc()}${checklist()}${documentsBlock()}${stepsBlock()}${founder()}${clientBlock()}${videosBlock()}${faqBlock()}${consultation()}</main>${footer}`;
const filterGroup=(title,key,values,expanded=false)=>`<details class="filter-group" ${expanded?'open':''}><summary>${title}<span>+</span></summary><div>${values.map(v=>`<label class="check"><input type="checkbox" name="${key}" value="${v}"><span>${v}${key==='floors'?' эт.':''}</span></label>`).join('')}</div></details>`;
const filters=()=>`<div class="filters-head"><h3>Подбор проекта</h3><button class="reset" data-reset>Сбросить</button></div><div id="filter-groups"></div><fieldset class="filter-range"><legend>Площадь, м²</legend><div class="two-input"><input aria-label="Площадь от" data-min type="number" min="0" placeholder="От"><input aria-label="Площадь до" data-max type="number" min="0" placeholder="До"></div></fieldset>`;
const buildSteps=()=>section('construction-stages',`${head('От проекта до дома','Как организована<br>реализация проекта','До начала работ определяем роли бюро, подрядчика и профильных специалистов. Формат сопровождения фиксируем отдельно.')} ${gridItems([['Проверка проекта и сметы','Бюро поясняет решения, подрядчик рассчитывает объём работ и материалов. Заказчик согласует смету и график.'],['Подготовка площадки','Подрядчик организует подъезд, временные сети и размещение материалов. Проектировщики отвечают на вопросы по посадке дома.'],['Фундамент','Подрядчик выполняет основание по КР. Конструктор разъясняет расчётные решения; скрытые работы принимает специалист по технадзору.'],['Стены и кровля','Строители собирают несущие конструкции и закрывают контур. В рамках авторского надзора бюро проверяет соответствие проекту.'],['Инженерия и отделка','Профильные подрядчики монтируют системы. Бюро согласует изменения, которые влияют на архитектуру и смежные разделы.'],['Проверка и передача дома','Подрядчик передаёт исполнительные материалы и оборудование. Заказчик с техническим специалистом проверяет выполненные работы.']])}<div class="section-action">${formButton('Обсудить сопровождение стройки','Хочу обсудить роли специалистов и сопровождение строительства по проекту.')}</div>`);

const catalog=()=>`${header}<main>${section('catalog-intro',`<div class="crumbs"><a href="index.html">Главная</a><span>/</span><span>Каталог</span></div>${head('Проекты домов и коттеджей','Найдите свой<br>архитектурный характер','Выбирайте по стилю, площади и устройству дома. Сочетайте параметры — и сохраняйте ссылку на свою подборку.').replace('<h2>','<h1>').replace('</h2>','</h1>')}<div class="catalog-fast"><a href="#catalog">Перейти к проектам ↓</a>${formButton('Помочь с выбором','Хочу подобрать проект под свой участок.',true)}</div>`,'catalog-title') }<section class="section catalog-section" id="catalog" data-block="catalog"><div class="catalog-layout"><aside class="filters" aria-label="Фильтры каталога">${filters()}</aside><div class="catalog-results"><h2 id="selection-heading" class="selection-heading" hidden></h2><div class="catalog-toolbar"><span class="result-count" role="status"></span><button class="filter-toggle" data-action="filters">Фильтры ☷</button><select id="sort" aria-label="Сортировать проекты"><option value="default">Порядок в каталоге</option><option value="small">Сначала меньшая площадь</option><option value="large">Сначала большая площадь</option></select></div><div class="chips" aria-label="Выбранные фильтры"></div><div class="project-grid catalog-grid" id="project-grid"></div><div id="catalog-pagination" class="pagination"></div><p class="small catalog-note">Архитектурные концепции и проекты. Состав документации, точные размеры и возможность адаптации уточняются для выбранного варианта.</p></div></div></section>${section('catalog-brief',`${head('Подбор под ваши вводные','Не нашли подходящий вариант?','Участок и привычки семьи важнее готового названия проекта. Поможем определить приоритеты и подобрать направление.')}<form id="selection-form" class="selection-form"><label><span class="field-label">Какой дом рассматриваете?</span><select name="type"><option>Каменный дом</option><option>Деревянный дом</option><option>Каркасный дом</option><option>Пока выбираю</option></select></label><label><span class="field-label">Примерная площадь</span><select name="area"><option>До 150 м²</option><option>150–250 м²</option><option>250–400 м²</option><option>Больше 400 м²</option></select></label><button class="btn" type="submit">Получить подборку${arrow}</button></form>`,'panel')}${section('catalog-description',`${head('Архитектура под задачу','Выбирайте дом<br>под свой участок и семью')} ${gridItems([['Площадь и этажность','Начните с состава семьи и нужных помещений. Сравните одно- и двухэтажные решения без лишней площади.'],['Архитектурный стиль','Выберите близкие по характеру фасады, кровлю и материалы. Сохраните ссылку на подборку для обсуждения.'],['Особенности участка','Проверьте размеры, рельеф, ориентацию и подъезд вместе с архитектором — красивого фасада для выбора недостаточно.']])}<div class="section-action">${link('Индивидуальное проектирование','service.html')}</div>`)}${buildSteps()}${section('excursion',`${head('Увидеть стройку своими глазами','Экскурсия<br>на строящийся объект')}<div class="split-content"><div>${img('house506','Архитектура дома из портфолио')}</div><div><p class="lead">На действующей площадке можно оценить решения в работе и задать вопросы команде.</p><ul class="plain-list"><li>Технологии и последовательность строительства</li><li>Используемые материалы и узлы</li><li>Организация работ и взаимодействие специалистов</li></ul>${formButton('Записаться на экскурсию','Хочу записаться на экскурсию на строящийся объект. Дату и объект согласуем индивидуально.')}<p class="small">Дату и доступный для посещения объект согласуем индивидуально.</p></div></div>`,'panel')}${section('catalog-advantages',`${head('Сопровождение реализации','Проект остаётся ориентиром<br>на каждом этапе')} ${gridItems([['Соответствие проекту','Проверка решений на площадке относительно согласованной документации.'],['Участие архитектора','Разбор вопросов по замыслу, планировке и внешнему виду.'],['Раннее выявление отклонений','Обсуждение проблем до того, как они потребуют сложной переделки.'],['Качество исполнения','Проверка применяемых материалов и строительных решений.'],['Документирование','Фотофиксация и записи по согласованному формату сопровождения.'],['Интересы заказчика','Понятная коммуникация между владельцем и участниками строительства.']])}`)}${founder()}${consultation()}</main>${footer}`;


const project=()=>{
 const id=new URLSearchParams(location.search).get('id')||projects[0].id;
 const featured=projects.find(p=>p.id===id||p.catalogId===id),raw=(window.PROJECT_CATALOG||[]).find(p=>p.id===id);
 const p=featured||(raw?{...raw,tag:'Проект дома',floors:raw.floorCount,style:raw.style.join(' · ')||'По проекту',note:raw.note||'',url:'project.html?id='+encodeURIComponent(raw.id)}:legacyProjects.find(p=>p.id===id))||projects[0];
 const gallery=p.gallery||(p.id==='25'?['concept','concept2','concept3']:[p.image]).filter(Boolean);
 const styles=raw&&!featured?raw.style:(p.styleKeys||[p.style]);
 const relatedPool=[...projects,...(window.PROJECT_CATALOG||[]).filter(x=>!projects.some(p=>p.catalogId===x.id)).map(x=>({...x,tag:'Проект дома',floors:x.floorCount,style:x.style.join(' · '),styles:x.style,url:'project.html?id='+encodeURIComponent(x.id)}))];
 const related=relatedPool.filter(x=>x.id!==p.id&&(x.styleKeys||x.styles||[x.style]).some(t=>styles.includes(t))).slice(0,3);
 const title=p.heading||(p.area?`Проект дома ${p.area} м²`:'Архитектура частного дома')+(p.style&&p.style!=='По проекту'?' · '+p.style.toLowerCase():'');
 const paragraphs=p.text||[`${p.name}${p.area?' — проект площадью '+p.area+' м²':''}. ${p.floors?'В проекте предусмотрено этажей: '+p.floors+'. ':''}${p.style!=='По проекту'?'Архитектурное направление: '+p.style.toLowerCase()+'. ':''}Рассмотрите фасады и объём дома, чтобы выбрать идеи для обсуждения с архитектором.`, 'На консультации разберём планировку, расположение дома на участке и состав необходимых разделов. Точные параметры и технические решения проверяем по документации проекта.'];
 const features=Array.isArray(p.features?.[0])?p.features:[['Тип',p.tag],['Архитектура',p.style],...(p.area?[['Площадь',p.area+' м²']]:[]),...(p.floors?[['Этажность',String(p.floors)]]:[])];
 window.currentProject={...p,gallery};document.title=p.name+' — Проект дома';
 document.querySelector('meta[name="description"]')?.setAttribute('content',paragraphs[0]);
 return `${header}<main>${section('project-intro',`<div class="crumbs"><a href="index.html">Главная</a><span>/</span><a href="catalog.html">Проекты домов</a><span>/</span><span>${safeText(p.name)}</span></div>${label(p.tag)}<h1>${safeText(p.name)}</h1>`,'project-intro')}
 <section class="gallery-section" id="project-gallery" data-block="project-gallery"><div class="gallery-main">${img(gallery[0],p.name,'id="main-project-image"')}<div class="gallery-controls"><button data-gallery-prev aria-label="Предыдущее изображение">←</button><span class="gallery-count">${gallery.length?'01':'00'} / ${String(gallery.length).padStart(2,'0')}</span><button data-gallery-next aria-label="Следующее изображение">→</button></div></div><div class="container thumbs">${gallery.map((im,i)=>`<button class="thumb ${i===0?'active':''}" data-thumb="${i}" aria-label="Изображение ${i+1}">${img(im,p.name+' — вид '+(i+1))}</button>`).join('')}</div></section>
 <section class="project-specs" data-block="project-specs"><div class="spec"><span>Площадь дома</span><strong>${p.area?p.area+' м²':'Уточняем'}</strong></div><div class="spec"><span>${p.floors?'Этажность':'Тип проекта'}</span><strong>${p.floors?(p.floors===1?'1 этаж':p.floors+' этажа'):'Частный дом'}</strong></div><div class="spec"><span>Стоимость проекта</span><strong>По запросу</strong></div>${formButton('Обсудить проект','Интересует проект «'+p.name+'». Обсудим архитектуру, планировку и состав работ.')}</section>
 ${section('project-description',`<div class="project-body"><div>${label('Описание проекта')}<h2>${safeText(title)}</h2>${paragraphs.map(t=>`<p>${safeText(t)}</p>`).join('')}<p class="small">${safeText(p.note||'')}</p>${raw&&!featured?`<a class="text-link" href="${safeText(p.source)}" target="_blank" rel="noopener">Источник проекта ↗</a>`:''}</div><div class="project-detail-list">${label('Характеристики')}<h3>Архитектурные решения</h3>${features.map(([a,b])=>`<div class="detail-row"><span>${safeText(a)}</span><strong>${safeText(b)}</strong></div>`).join('')}<p class="small">Площадь и состав документации подтвердим при обсуждении выбранного проекта.</p></div></div>`)}
 ${section('project-adaptation',`${head('Обсудим ваш дом','Взять этот проект<br>за отправную точку')} ${gridItems([['Ваш участок','Проверим размеры, рельеф, подъезд и ориентацию. Определим, как разместить дом и открытые зоны.'],['Ваша планировка','Обсудим состав семьи, нужные комнаты, приватность и хранение. Составим требования вместе.'],['Ваш проект','Определим архитектурные, конструктивные и инженерные разделы; согласуем этапы и подготовим предложение.']])}<div class="section-action">${formButton('Обсудить проект','Хочу обсудить проект «'+p.name+'» как отправную точку для моего дома.')}<a class="text-link" href="downloads/Project-Doma-Start-Checklist.pdf" download>Скачать чек-лист для первой встречи ↓</a></div>`,'panel')}
 ${section('related-projects',`${head('Продолжить выбор','Проекты в близком стиле',related.length?'Другие дома в том же архитектурном направлении.':'Поможем подобрать архитектурные решения в выбранном стиле.')}<div class="project-grid">${related.map(card).join('')}</div><div class="section-action">${link('Смотреть проекты этого стиля','catalog.html?style='+encodeURIComponent(styles[0]||''))}${link('Весь каталог','catalog.html')}</div>` )}</main>${footer}`;
};


document.body.innerHTML=({home,service,catalog,project}[page]||home)();
document.body.insertAdjacentHTML('beforeend',`<dialog id="contact" aria-labelledby="contact-title"><button class="close" data-close aria-label="Закрыть">×</button>${label('Начнём с вашей задачи')}<h2 id="contact-title">Обсудим ваш будущий дом</h2><p class="small" id="contact-context">Оставьте контакты, чтобы обсудить участок, пожелания и состав проекта.</p><form id="contact-form"><label><span class="field-label">Ваше имя</span><input name="name" autocomplete="given-name" placeholder="Как к вам обращаться" required maxlength="80"></label><label><span class="field-label">Телефон</span><input name="phone" type="tel" autocomplete="tel" placeholder="+7 (___) ___-__-__" required maxlength="22"></label><label class="consent"><input type="checkbox" required><span>Согласен с <a style="text-decoration:underline" href="https://xn--80ahculiddjx.com/politika-konfidencialnosti/" target="_blank" rel="noopener">политикой обработки персональных данных</a>.</span></label><button type="submit" class="btn">Обсудить проект${arrow}</button><p class="small">Демонстрационная форма: данные не отправляются и не сохраняются.</p><div class="toast" id="form-status" role="status" hidden></div></form></dialog><dialog id="lightbox" aria-label="Просмотр изображения"><button class="close" data-close aria-label="Закрыть изображение">×</button><img alt="Увеличенное изображение проекта"></dialog><dialog id="menu" class="mobile-drawer" aria-label="Меню"><button class="close" data-close aria-label="Закрыть меню">×</button>${label('Проект дома')}<div class="menu-links"><a href="index.html">Главная</a><a href="service.html">Проектирование</a><a href="catalog.html">Проекты домов</a><a href="index.html#about">О бюро</a><a href="index.html#journal">Журнал</a><a href="#contacts" data-menu-close>Контакты</a></div></dialog><dialog id="filter-dialog" class="mobile-drawer" aria-label="Фильтры проектов"><button class="close" data-close aria-label="Закрыть фильтры">×</button><div class="filters">${filters()}</div><button class="btn" data-close>Показать проекты${arrow}</button></dialog>`);
function openDialog(id){const d=$('#'+id);if(!d.open)d.showModal();document.body.style.overflow='hidden';}
function closeDialog(d){d.close();document.body.style.overflow='';}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.style.overflow='');d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);}});});
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){closeDialog(close.closest('dialog'));return;}const m=e.target.closest('[data-menu-close]');if(m)closeDialog($('#menu'));const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='form'){$('#form-status').hidden=true;$('#contact-title').textContent=a.textContent.trim().replace('↗︎','');$('#contact-context').textContent=a.dataset.context|| (window.currentProject?'Обсудим проект «'+window.currentProject.name+'», его архитектуру, планировку и состав работ.':'Оставьте контакты, чтобы обсудить участок, пожелания и состав проекта.');openDialog('contact');}else if(action==='menu')openDialog('menu');else if(action==='filters')openDialog('filter-dialog');}const g=e.target.closest('[data-gallery]');if(g){$('#lightbox img').src='assets/'+g.dataset.gallery+'.webp';$('#lightbox img').alt=g.getAttribute('aria-label')||'Архитектура и документация бюро';openDialog('lightbox');}});
$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const phone=e.target.elements.phone;const digits=phone.value.replace(/[^0-9]/g,'');if(digits.length<10||digits.length>15){phone.setCustomValidity('Укажите телефон: от 10 до 15 цифр.');phone.reportValidity();return;}const status=$('#form-status');status.hidden=false;status.textContent='Проверка формы прошла. Это демонстрация: заявка не отправлена. Связаться с бюро можно по номеру +7 (499) 674-06-71.';});
if($('#calc-form')){
 const calcForm=$('#calc-form');
 calcForm.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);$('#form-status').hidden=true;$('#contact-title').textContent='Получить расчёт проекта';$('#contact-context').textContent=`Площадь: ${f.get('area')} м². Состав: ${f.get('package')}. ${f.get('stage')}. Уточним задачу и подготовим индивидуальное предложение.`;openDialog('contact');});
}
if(page==='project'){const p=window.currentProject,list=p.gallery;let n=0;function update(){const im=$('#main-project-image');if(!im||!list[n])return;im.src='assets/'+list[n]+'.webp';$('.gallery-count').textContent=String(n+1).padStart(2,'0')+' / '+String(list.length).padStart(2,'0');$$('[data-thumb]').forEach((b,i)=>b.classList.toggle('active',i===n));}$$('[data-thumb]').forEach(b=>b.addEventListener('click',()=>{n=Number(b.dataset.thumb);update();}));$('[data-gallery-prev]').addEventListener('click',()=>{n=(n+list.length-1)%list.length;update();});$('[data-gallery-next]').addEventListener('click',()=>{n=(n+1)%list.length;update();});$('#main-project-image')?.addEventListener('click',()=>{if(!list[n])return;$('#lightbox img').src='assets/'+list[n]+'.webp';openDialog('lightbox');});if(list.length<=1){$('[data-gallery-prev]').hidden=true;$('[data-gallery-next]').hidden=true;}}

if(page==='catalog'){
 const originalCatalog=window.PROJECT_CATALOG||[];
 const curated=projects.map(p=>({...p,id:p.catalogId||p.id,area:null,floors:[],floorCount:null,style:p.styleKeys||[p.style],material:[],floorTags:[],dimensions:[],features:p.filters?.features||[],rooms:[],purpose:[],type:[],dimensionsVerified:false}));
 const all=[...curated,...originalCatalog.filter(x=>!curated.some(p=>p.id===x.id))],groups=window.PROJECT_FILTERS||[],params=new URLSearchParams(location.search),state={min:params.get('min')||'',max:params.get('max')||'',page:Number(params.get('p'))||1};
 for(const g of groups)state[g.key]=params.getAll(g.key).filter(v=>g.options.some(o=>o.value===v));
 for(const k of ['min','max'])state[k]=/^\d{1,6}$/.test(state[k])?state[k]:'';state.page=Number.isFinite(state.page)?Math.max(1,Math.floor(state.page)):1;
 const groupHTML=groups.map(g=>filterGroup(g.title,g.key,g.options.map(o=>o.value),['style','material','floors'].includes(g.key))).join('');
 document.querySelectorAll('#filter-groups').forEach(e=>{e.innerHTML=groupHTML;});
 const catalogCard=p=>`<a class="project-card" href="project.html?id=${encodeURIComponent(p.id)}"><div class="image-wrap">${img(p.image,p.name)}<span class="round">${arrow}</span></div><div class="project-meta"><span>${p.style.slice(0,2).join(' / ')||'Архитектурный проект'}</span><span>${p.area?p.area+' м²':'Площадь по запросу'}</span></div><h3>${safeText(p.name)}</h3><p>${p.floorCount?p.floorCount+' эт.':'Этажность по запросу'}${p.material.length?' · '+p.material.slice(0,2).join(', '):''}</p></a>`;
 function sync(){for(const g of groups)$$(`input[name="${g.key}"]`).forEach(x=>x.checked=state[g.key].includes(x.value));for(const key of ['min','max'])$$(`[data-${key}]`).forEach(x=>x.value=state[key]);}
 function updateURL(){const q=new URLSearchParams();for(const g of groups)for(const v of state[g.key])q.append(g.key,v);for(const k of ['min','max'])if(state[k])q.set(k,state[k]);if(state.page>1)q.set('p',state.page);if($('#sort').value!=='default')q.set('sort',$('#sort').value);history.replaceState(null,'',location.pathname+(q.size?'?'+q.toString():''));}
 function render(){let found=all.filter(p=>groups.every(g=>!state[g.key].length||state[g.key].some(v=>(p[g.key]||[]).includes(v)))&&(!state.min||(p.area&&p.area>=Number(state.min)))&&(!state.max||(p.area&&p.area<=Number(state.max))));const sort=$('#sort').value;if(sort!=='default')found.sort((a,b)=>sort==='small'?(a.area??Infinity)-(b.area??Infinity):(b.area??-1)-(a.area??-1));const count=15,totalPages=Math.max(1,Math.ceil(found.length/count));state.page=Math.max(1,Math.min(totalPages,state.page));const shown=found.slice((state.page-1)*count,state.page*count);$('#project-grid').innerHTML=shown.length?shown.map(catalogCard).join(''):`<div class="empty"><h3>Точного совпадения пока нет</h3><p>Уберите один из параметров или обсудите индивидуальный проект.</p>${formButton('Помочь с подбором','Не нашёл проект по выбранным параметрам.')}<button class="text-link reset" data-reset>Сбросить фильтры</button></div>`;$('.result-count').textContent=`Найдено проектов: ${found.length}`;const selectionParts=groups.flatMap(g=>state[g.key].map(v=>g.key==='floors'?v+' эт.':v));const heading=$('#selection-heading');heading.hidden=!selectionParts.length;heading.textContent=selectionParts.length?'Дома: '+selectionParts.join(' · '):'';document.title=selectionParts.length?heading.textContent+' — Проект дома':'Каталог проектов домов — Проект дома';const entries=[];for(const g of groups)state[g.key].forEach(v=>entries.push({k:g.key,v,t:v}));for(const k of ['min','max'])if(state[k])entries.push({k,v:state[k],t:(k==='min'?'От ':'До ')+state[k]+' м²'});$('.chips').innerHTML=entries.map(x=>`<button class="chip" data-remove="${x.k}" data-value="${x.v}">${x.t} ×</button>`).join('');if(state.dimensions?.length)$('.chips').insertAdjacentHTML('beforeend','<p class="small dimension-note">Габариты — категория подбора. Точные размеры проверяем по документации выбранного проекта.</p>');$('#catalog-pagination').innerHTML=`<button class="btn outline" data-catalog-page="${state.page-1}" ${state.page===1?'disabled':''}>← Назад</button><span>${state.page} / ${totalPages}</span><button class="btn outline" data-catalog-page="${state.page+1}" ${state.page===totalPages?'disabled':''}>Далее →</button>`;sync();updateURL();}
 if(params.get('sort'))$('#sort').value=params.get('sort');render();
 document.addEventListener('change',e=>{const el=e.target;if(groups.some(g=>g.key===el.name)){state[el.name]=el.checked?[...new Set([...state[el.name],el.value])]:state[el.name].filter(v=>v!==el.value);state.page=1;render();}if(el.id==='sort'){state.page=1;render();}});
 document.addEventListener('input',e=>{for(const k of ['min','max'])if(e.target.hasAttribute('data-'+k)){state[k]=e.target.value;state.page=1;render();}});
 document.addEventListener('click',e=>{if(e.target.closest('[data-reset]')){groups.forEach(g=>state[g.key]=[]);state.min='';state.max='';state.page=1;render();}const b=e.target.closest('[data-remove]');if(b){const k=b.dataset.remove;state[k]=Array.isArray(state[k])?state[k].filter(v=>v!==b.dataset.value):'';state.page=1;render();}const pag=e.target.closest('[data-catalog-page]');if(pag){state.page=Number(pag.dataset.catalogPage);render();$('#catalog').scrollIntoView({behavior:'smooth'});}});
}
if($('#selection-form'))$('#selection-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);$('#contact-title').textContent='Подберём проект дома';$('#contact-context').textContent=`Интересует ${f.get('type').toLowerCase()}, площадь ${f.get('area').toLowerCase()}. Обсудим участок и подходящие варианты.`;$('#form-status').hidden=true;openDialog('contact');});
$$('[data-checklist]').forEach(x=>x.addEventListener('change',()=>{const count=$$('[data-checklist]:checked').length;$('.checklist-progress').textContent=`Отмечено: ${count} из 18`; }));

$("#contact-form input[name=phone]").addEventListener("input",e=>e.target.setCustomValidity(""));
